-- ==============================================================================
-- Production SQL Script 03: Store Settings, Delivery Zones & Catalog Seed Data
-- Project: Vasu Crackers
-- Description: Seeds store settings, delivery zones, 29 categories, 216 products from public/products.csv,
--              inventory balances, festival combos, and automatic discount price sync.
-- ==============================================================================

-- 1. SEED STORE SETTINGS
ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value;

-- 2. SEED REGIONAL DELIVERY ZONES
ON CONFLICT (id) DO UPDATE SET
  zone_name = EXCLUDED.zone_name,
  state_codes = EXCLUDED.state_codes,
  min_order_amount = EXCLUDED.min_order_amount,
  delivery_fee = EXCLUDED.delivery_fee,
  estimated_days = EXCLUDED.estimated_days;

-- 3. CLEAR EXISTING CATALOG & TRANSACTIONAL DATA (RE-RUNNABLE SEED)
TRUNCATE TABLE 
  bill_items,
  bills,
  order_items, 
  orders, 
  combo_items, 
  combos, 
  inventory_movements, 
  inventory, 
  products, 
  categories 
CASCADE;

-- 4. INSERT 29 CATEGORIES (FROM public/products.csv)

-- 5. INSERT 216 PRODUCTS (FROM public/products.csv)

-- 6. INSERT WAREHOUSE INVENTORY BALANCES (FROM public/products.csv)

-- 7. INSERT POPULAR FESTIVAL COMBOS
ON CONFLICT (id) DO NOTHING;

ON CONFLICT DO NOTHING;

-- 8. AUTOMATICALLY SYNCHRONIZE SELLING PRICES WITH GLOBAL STORE DISCOUNT
CREATE OR REPLACE FUNCTION sync_product_prices_with_discount()
RETURNS TRIGGER AS $$
DECLARE
  v_discount NUMERIC;
BEGIN
  IF NEW.key = 'discount_percentage' THEN
    v_discount := COALESCE(NULLIF(NEW.value, '')::NUMERIC, 90);
    UPDATE products
    SET 
      selling_price = ROUND(mrp * ((100.0 - v_discount) / 100.0), 2),
      updated_at = NOW()
    WHERE mrp IS NOT NULL AND mrp > 0;
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_sync_discount_prices ON store_settings;
CREATE TRIGGER trg_sync_discount_prices
AFTER INSERT OR UPDATE OF value ON store_settings
FOR EACH ROW
WHEN (NEW.key = 'discount_percentage')
EXECUTE FUNCTION sync_product_prices_with_discount();

-- Immediate execution so seed products match configured discount percentage
DO $$
DECLARE
  v_discount NUMERIC := 90;
BEGIN
  SELECT COALESCE(NULLIF(value, '')::NUMERIC, 90) INTO v_discount
  FROM store_settings
  WHERE key = 'discount_percentage'
  LIMIT 1;

  UPDATE products
  SET 
    selling_price = ROUND(mrp * ((100.0 - v_discount) / 100.0), 2),
    updated_at = NOW()
  WHERE mrp IS NOT NULL AND mrp > 0;
END $$;
